/* Shared directory: search, compare, dated updates. No development tools. */
(()=>{'use strict';
const D=window.DIRECTORY;if(D?.packed){const p=D.packed;D.items=p.rows.map(r=>Object.fromEntries(p.keys.flatMap((k,i)=>r[i]<0?[]:[[k,p.pool[r[i]]]])));delete D.packed;}if(!D){document.querySelector('main').innerHTML='<div class="empty"><h2>Catalog could not load</h2><p>Please reload to try again.</p></div>';return;}
const $=s=>document.querySelector(s), E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safe=u=>{try{const x=new URL(u,location.href);return ['https:','http:'].includes(x.protocol)?x.href:'';}catch{return '';}};
const link=(u,t)=>safe(u)?`<a href="${E(safe(u))}" target="_blank" rel="noopener noreferrer">${E(t)} ↗</a>`:E(t);
const fold=v=>String(v??'').normalize('NFKC').toLowerCase();
const same=(a,b)=>fold(a)===fold(b);
const unique=a=>[...new Map(a.filter(Boolean).map(v=>[fold(v),v])).values()].sort((a,b)=>a.localeCompare(b));
const byId=new Map(D.items.map(p=>[p.id,p])), key='simple-directory-'+D.id+'-selected', f={q:'',brand:'',retailer:'',category:'',market:'',currency:'',character:'',since:'',dateKind:'checked',min:'',max:'',evidence:'',sort:'recent'};let page=1, route='',selected=new Set,variants=new Map,newsLimit=20,toastTimer;
try{selected=new Set(JSON.parse(localStorage.getItem(key)||'[]').filter(id=>byId.has(id)));if(!localStorage.getItem(key)&&D.legacyStorage){let old=JSON.parse(localStorage.getItem(D.legacyStorage)||'[]');if(!Array.isArray(old))old=old.selected||old.ids||[];selected=new Set(old.filter(id=>byId.has(id)));}}catch{}
for(const p of D.items)p.search=[p.name,p.brand,p.category,p.retailer,p.market,p.character,p.material,p.dimensions,p.features,p.variant,...(p.aliases||[])].join(' ').normalize('NFKC').toLowerCase();
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3500)}
function persist(){try{localStorage.setItem(key,JSON.stringify([...selected]))}catch{toast('Browser storage is unavailable. Export your selected products to keep them.')}}
const fmt=p=>p.priceText|| (p.amount!=null?`${p.currency||''} ${Number(p.amount).toLocaleString('en-US',{maximumFractionDigits:2,minimumFractionDigits:2})}`:'Price not verified');
const thumb=p=>p.image?`<img src="${E(safe(p.image))}" alt="${E(p.name)}" loading="lazy" decoding="async">`:'<span class="no-photo">Photo not verified</span>';
const options=(values,first)=>`<option value="">${E(first)}</option>`+unique(values).map(v=>`<option value="${E(v)}">${E(v)}</option>`).join('');
function loadFilters(){for(const field of ['brand','retailer','category','market','currency','character']){$('#f-'+field).innerHTML=options(D.items.flatMap(p=>field==='category'?[p.category,...(p.categories||[])]:field==='retailer'?[p.retailer,...(p.retailers||[])]:[p[field]]),'All '+({category:'categories',currency:'currencies',character:'characters',brand:'brands',retailer:'retailers',market:'markets'}[field]));}$('#character-filter').hidden=!D.items.some(p=>p.character);$('#f-evidence').innerHTML=options(D.items.map(p=>p.evidence),'All evidence');}
function filtered(){const terms=f.q.trim().normalize('NFKC').toLowerCase().split(/\s+/).filter(Boolean);return D.items.filter(p=>terms.every(t=>p.search.includes(t))&&(!f.brand||same(p.brand,f.brand))&&(!f.retailer||same(p.retailer,f.retailer)||p.retailers?.some(v=>same(v,f.retailer)))&&(!f.category||same(p.category,f.category)||p.categories?.some(v=>same(v,f.category)))&&(!f.market||same(p.market,f.market))&&(!f.currency||same(p.currency,f.currency))&&(!f.character||same(p.character,f.character))&&(!f.evidence||same(p.evidence,f.evidence))&&(!f.since||(p[f.dateKind]&&p[f.dateKind]>=f.since))&&(!f.min||(p.amount!=null&&p.amount>=+f.min))&&(!f.max||(p.amount!=null&&p.amount<=+f.max))).sort((a,b)=>f.sort==='name'?a.name.localeCompare(b.name):f.sort==='brand'?a.brand.localeCompare(b.brand)||a.name.localeCompare(b.name):f.sort==='price-asc'||f.sort==='price-desc'?a.currency.localeCompare(b.currency)||(a.amount==null)-(b.amount==null)||((f.sort==='price-asc'?1:-1)*((a.amount??0)-(b.amount??0))):String(b[f.sort==='launch'?'launch':f.sort==='listed'?'listed':f.sort==='added'?'added':'checked']||'').localeCompare(String(a[f.sort==='launch'?'launch':f.sort==='listed'?'listed':f.sort==='added'?'added':'checked']||''))||a.name.localeCompare(b.name));}
function groups(rows){const map=new Map;for(const p of rows){const id=p.group||p.id;if(!map.has(id))map.set(id,[]);map.get(id).push(p)}return [...map.entries()];}
function card([gid,ps]){const p=ps.find(x=>x.id===variants.get(gid))||ps[0];return `<article class="card ${selected.has(p.id)?'selected':''}" data-card="${E(p.id)}"><button class="photo" data-detail="${E(p.id)}" aria-label="View ${E(p.name)}">${thumb(p)}${ps.length>1?`<span class="tag">${ps.length} offers / variants</span>`:''}</button><div class="card-body"><p class="card-brand">${E(p.brand||'Brand not verified')}</p><h2><button data-detail="${E(p.id)}">${E(p.groupName||p.name)}</button></h2><p class="meta">${E(p.category)} · ${E(p.retailer||p.market)}</p>${ps.length>1?`<label class="variant-picker">Choose an exact offer<select data-variant="${E(gid)}">${ps.map(v=>`<option value="${E(v.id)}" ${p.id===v.id?'selected':''}>${E(v.variant||v.name)} · ${E(fmt(v))} · ${E(v.retailer)}</option>`).join('')}</select></label>`:''}<p class="price">${E(fmt(p))}</p><p class="small">${E(p.currency?`${p.market||'Market not specified'} · `:'')}${E(p.priceDate?'Price observed '+p.priceDate:'Price date not verified')}</p><div class="card-bottom"><label class="pick"><input type="checkbox" data-pick="${E(p.id)}" ${selected.has(p.id)?'checked':''}> Compare</label>${safe(p.url)?`<a class="source-link" href="${E(safe(p.url))}" target="_blank" rel="noopener noreferrer">Source ↗</a>`:''}</div></div></article>`}
function count(){const n=selected.size;$('#nav-count').textContent=n;$('#nav-count').hidden=!n;$('#compare-bar').hidden=!n||route!=='search';$('#bar-count').textContent=`${n} selected`;$('#compare-heading').textContent=`Compare products${n?' ('+n+')':''}`;}
function draw(){const rows=filtered(),gs=groups(rows),pages=Math.max(1,Math.ceil(gs.length/24));page=Math.min(page,pages);$('#result-count').innerHTML=`<strong>${gs.length.toLocaleString()} ${D.unit||'products'}</strong> · ${rows.length.toLocaleString()} matching ${D.id==='luggage-atlas'?'offers':'records'}`;$('#result-total').textContent=`${D.items.length.toLocaleString()} records in this directory`;$('#cards').innerHTML=gs.slice((page-1)*24,page*24).map(card).join('')||'<div class="empty" style="grid-column:1/-1"><h2>No matching products</h2><p>Try fewer keywords or clear your filters.</p><button data-reset>Reset filters</button></div>';$('#page-label').textContent=`Page ${page} of ${pages}`;$('#prev').disabled=page===1;$('#next').disabled=page===pages;$('#export-results').disabled=!rows.length;count();const matches=(D.brands||[]).filter(b=>!f.q||[b.name,...(b.aliases||[])].join(' ').toLowerCase().includes(f.q.toLowerCase()));$('#brand-matches').hidden=!(D.brands?.length&&f.q&&matches.length);$('#brand-matches').innerHTML=`<summary>${matches.length} matching brand profiles</summary><div class="brand-grid">${matches.map(b=>`<button data-brand="${E(b.name)}">${E(b.name)}</button>${b.url?link(b.url,'Brand website'):''}`).join('')}</div>`;}
function reset(){for(const k of Object.keys(f))f[k]=k==='sort'?'recent':k==='dateKind'?'checked':'';page=1;$('#search').value='';for(const el of document.querySelectorAll('[data-filter]'))el.value=f[el.dataset.filter];draw()}
function toggle(id){if(selected.has(id))selected.delete(id);else selected.add(id);persist();count();if(route==='compare')renderCompare();else draw();}
const fields=[['Brand','brand'],['Category','category'],['Retailer / source','retailer'],['Market','market'],['Exact offer / pack','variant'],['Observed price',p=>fmt(p)],['Price basis','priceNote'],['Price observed','priceDate'],['Material','material'],['Dimensions','dimensions'],['Weight','weight'],['Features','features'],['Manufacturer / factory','manufacturer'],['Availability at check','availability'],['Launch date','launch'],['Retailer listing date','listed'],['Added to directory','added'],['Source checked','checked'],['Sales / demand evidence','sales'],['Evidence status','evidence'],['Photo scope','imageNote'],['Catalog date basis','catalogDateBasis'],['Limitations','note']];
function renderCompare(){const ps=[...selected].map(id=>byId.get(id)).filter(Boolean);count();$('#export-selected').disabled=!ps.length;$('#clear-selected').disabled=!ps.length;if(!ps.length){$('#comparison').innerHTML='<div class="empty"><h2>Your comparison starts here</h2><p>Select Compare on product cards, then return here.</p><a class="button primary" href="#search">Find products</a></div>';return;}const per=4,pages=Math.ceil(ps.length/per),cp=Math.min(Number($('#compare-page').dataset.page||1),pages);$('#compare-page').dataset.page=cp;const shown=ps.slice((cp-1)*per,cp*per);$('#comparison').innerHTML=`<div class="compare-scroll"><table class="compare-table"><thead><tr><th>Product</th>${shown.map(p=>`<td>${thumb(p)}<div class="compare-title">${E(p.name)}</div><button data-pick-button="${E(p.id)}">Remove</button></td>`).join('')}</tr></thead><tbody>${fields.map(([label,field])=>`<tr><th>${E(label)}</th>${shown.map(p=>`<td>${E((typeof field==='function'?field(p):p[field])||'Not verified')}</td>`).join('')}</tr>`).join('')}<tr><th>Original source</th>${shown.map(p=>`<td>${link(p.url,'Open product source')}${p.specSource?'<p>'+link(p.specSource,'Specification source')+'</p>':''}${p.salesSource?'<p>'+link(p.salesSource,'Sales evidence')+'</p>':''}</td>`).join('')}</tr></tbody></table></div>`;$('#compare-page').hidden=pages<2;$('#compare-page-label').textContent=`${cp} of ${pages} groups · all ${ps.length} selected items are in the CSV`;$('#compare-prev').disabled=cp===1;$('#compare-next').disabled=cp===pages;}
function exportCSV(ps,name){const cols=[['ID','id'],['Product','name'],...fields,['Currency','currency'],['Source URL','url'],['Photo URL','image'],['Photo source','imageSource'],['Specification source','specSource'],['Sales source','salesSource'],['Manufacturer source','manufacturerSource']];const cell=v=>{v=String(v??'');if(/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"'};const rows=[cols.map(([n])=>n),...ps.map(p=>cols.map(([,k])=>{const v=typeof k==='function'?k(p):p[k];return ['url','image','imageSource','specSource','salesSource','manufacturerSource'].includes(k)?(v?safe(v):''):v}))];const blob=new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=D.id+'-'+name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast(`Exported ${ps.length} records`)}
function detail(id){const p=byId.get(id);if(!p)return;const photos=[{url:p.image,caption:p.imageNote},...(p.gallery||[])].filter(x=>x.url);$('#detail-body').innerHTML=`<div class="detail-grid"><div>${photos.length?`<img id="detail-photo" class="detail-photo" src="${E(safe(photos[0].url))}" alt="${E(p.name)}"><p id="detail-caption" class="small">${E(photos[0].caption||'Source product photo; confirm exact variant.')}</p><div class="gallery">${photos.map(x=>`<button data-photo="${E(safe(x.url))}" data-caption="${E(x.caption||'Source product photo')}" aria-label="View photo: ${E(x.caption||p.name)}"><img src="${E(safe(x.url))}" alt="${E(x.caption||p.name)}" loading="lazy"></button>`).join('')}</div>`:'<div class="no-photo">Photo not verified</div>'}</div><div><p class="eyebrow">${E(p.brand)}</p><h2>${E(p.name)}</h2><p class="price">${E(fmt(p))}</p><p class="small">${E(p.priceNote)}</p><div class="fact-links"><button class="primary" data-detail-pick="${E(id)}">${selected.has(id)?'Remove from comparison':'Add to comparison'}</button>${link(p.url,'Open source')}</div><dl class="facts">${fields.filter(([,k])=>typeof k!=='function').map(([n,k])=>`<dt>${E(n)}</dt><dd>${E(p[k]||'Not verified')}</dd>`).join('')}</dl>${p.specSource?'<p>'+link(p.specSource,'Specification source')+'</p>':''}${p.salesSource?'<p>'+link(p.salesSource,'Sales evidence')+'</p>':''}${p.manufacturerSource?'<p>'+link(p.manufacturerSource,'Manufacturer evidence')+'</p>':''}${p.offers?.length?`<h3>Other retailer offers</h3>${p.offers.map(o=>`<p>${link(o.url,o.retailer)} · ${E(o.price)}<br><span class="small">${E(o.variant)} · ${E(o.checked)} · ${E(o.market)}</span></p>`).join('')}`:''}</div></div>`;$('#detail').showModal()}
function renderNews(){const q=$('#news-search').value.toLowerCase(),type=$('#news-type').value,rows=D.news.filter(n=>(!q||[n.title,n.summary,n.market,n.type].join(' ').toLowerCase().includes(q))&&(!type||n.type===type)).sort((a,b)=>String(b.date).localeCompare(String(a.date)));$('#news-count').textContent=`${rows.length} dated updates`;$('#news-list').innerHTML=rows.slice(0,newsLimit).map(n=>`<article class="news-card"><div class="news-date"><b>${E(n.type||'Source update')}</b><span>${E(n.date||'Date not verified')}</span><span>${E(n.market||'')}</span></div><h3>${E(n.title)}</h3><p>${E(n.summary)}</p><p class="small">${E(n.dateLabel||'Source date')}${n.eventDate?' · Event: '+E(n.eventDate):''}${n.checked?' · Checked: '+E(n.checked):''}</p><div class="news-links">${(n.sources||[]).map(s=>link(s.url,s.label||'Read source')).join('')}</div></article>`).join('')||'<div class="empty"><h2>No updates match</h2><p>Try another search or update type.</p></div>';$('#more-news').hidden=rows.length<=newsLimit}
function navigate(){const hash=location.hash.slice(1),aliases={directory:'search',catalog:'search',products:'search',brands:'search',workbench:'compare',overview:'news',weekly:'news',tutorial:'guide'};route=aliases[hash]||(['search','compare','news','guide'].includes(hash)?hash:'search');for(const el of document.querySelectorAll('[data-view]'))el.hidden=el.dataset.view!==route;for(const a of document.querySelectorAll('[data-route]')){if(a.dataset.route===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')}if(route==='search')draw();if(route==='compare')renderCompare();if(route==='news')renderNews();count();}
$('#search').addEventListener('input',e=>{f.q=e.target.value;page=1;draw()});for(const el of document.querySelectorAll('[data-filter]'))el.addEventListener('change',e=>{f[el.dataset.filter]=e.target.value;page=1;draw()});
$('#prev').onclick=()=>{page--;draw();$('#search').scrollIntoView({block:'start'})};$('#next').onclick=()=>{page++;draw();$('#search').scrollIntoView({block:'start'})};
$('#clear-selected').onclick=()=>{selected.clear();persist();renderCompare()};$('#bar-clear').onclick=()=>{selected.clear();persist();draw()};$('#export-results').onclick=()=>exportCSV(filtered(),'search-results');$('#export-selected').onclick=()=>exportCSV([...selected].map(id=>byId.get(id)).filter(Boolean),'selected');
for(const [id,delta]of [['compare-prev',-1],['compare-next',1]])$('#'+id).onclick=()=>{$('#compare-page').dataset.page=Number($('#compare-page').dataset.page||1)+delta;renderCompare()};
$('#detail-close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail'))$('#detail').close()});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-reset'))reset();if(b.dataset.detail)detail(b.dataset.detail);if(b.dataset.pickButton)toggle(b.dataset.pickButton);if(b.dataset.detailPick){toggle(b.dataset.detailPick);b.textContent=selected.has(b.dataset.detailPick)?'Remove from comparison':'Add to comparison'}if(b.dataset.photo){$('#detail-photo').src=b.dataset.photo;$('#detail-caption').textContent=b.dataset.caption}if(b.dataset.brand){f.brand=b.dataset.brand;$('#f-brand').value=f.brand;f.q='';$('#search').value='';page=1;draw()}if(b.dataset.seek){const v=$('#tutorial-video');v.currentTime=Number(b.dataset.seek);v.play().catch(()=>toast('Press Play on the video to start.'))}});
document.addEventListener('change',e=>{if(e.target.dataset.pick)toggle(e.target.dataset.pick);if(e.target.dataset.variant){variants.set(e.target.dataset.variant,e.target.value);draw()}});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'){e.target.hidden=true;const msg=document.createElement('span');msg.className='no-photo';msg.textContent='Photo unavailable · open source';e.target.after(msg)}},true);
$('#news-search').oninput=()=>{newsLimit=20;renderNews()};$('#news-type').innerHTML=options(D.news.map(n=>n.type),'All updates');$('#news-type').onchange=()=>{newsLimit=20;renderNews()};$('#more-news').onclick=()=>{newsLimit+=20;renderNews()};
$('#catalog-date').textContent=`Latest catalog review: ${D.reviewed||'Not verified'}`;$('#news-status').textContent=`Daily checks are scheduled. Latest catalog review: ${D.reviewed||'Not verified'}. News keeps its own source and check dates. Coverage remains partial; no update is claimed until verified.`;
loadFilters();const params=new URLSearchParams(location.search);if(params.has('q')){f.q=params.get('q');$('#search').value=f.q}addEventListener('hashchange',navigate);navigate();
window.DirectoryTest={filtered,groups,byId,selected,fields,data:D};
})();
